interface Room {
    _id?: string;
    roomNumber: number;
    floor: number;
    isScaled?: boolean;
    maxCapacity: number;
    isQuarantined?: boolean;
    patientNumbers?: number[];
}

interface Patient {
    _id?: string;
    patientNumber: number;
    firstName: string;
    lastName: string;
    isQuarantined: boolean;
    dateOfBirth?: string;
    createdAt?: string;
    updatedAt?: string;
    __v?: number;
    room: Room;
}


interface MapSvgProps {
    screenWidth: number;
    MAP_SCALE_FACTOR: number;
    rooms: Room[] | undefined;
    patients: Patient[] | undefined;
}

